<script>
	(function (window, document) {
		
		let gamepad_list = {};
		let selected_index;
		let touchpad_press = false;
		let button_layout = {
			'xbox': ['A', 'B', 'X', 'Y', 'LB', 'RB', 'LT', 'RT', 'Back', 'Start', 'LAnalog', 'RAnalog', 'Up', 'Down', 'Left', 'Right', 'Guide'],
			'ps': ['X', 'O', 'Square', 'Triangle', 'L1', 'R1', 'L2', 'R2', 'Option', 'Menu', 'LAnalog', 'RAnalog', 'Up', 'Down', 'Left', 'Right', 'Home', 'Touchpad'],
		};
		
		let type_choice = window.document.getElementById("gamepad_type_choice");
		let gamepad_choice = window.document.getElementById("gamepad_choice");
		
		let xbox = window.document.getElementById("xbox");
		let playStation = window.document.getElementById("playStation");
		let statusInfo = window.document.getElementById("display-bar");
		
		let vibrationBtn = window.document.getElementById("vibration-btn");
		
		const determineModel = (id) => {
			id = id.toLowerCase();
			let model;
			
			if(id.indexOf('xbox') !== -1 || id.indexOf('joystick') !== -1) {
				model = 'xbox';
			} else if(id.indexOf('playstation') !== -1 || id.indexOf('ps') !== -1 || id.indexOf('dual') !== -1) {
				model = 'ps';
			} else {
				model = 'ps';
			}
			
			type_choice.value = model;
			if(model === "xbox") {
				xbox.style.display = "block";
				playStation.style.display = "none";
			} else if (model === "ps") {
				xbox.style.display = "none";
				playStation.style.display = "block";
			}
		}
		
		gamepad_choice.addEventListener("change", () => {
			let id = gamepad_list[Number(gamepad_choice.value)].id;
			
			determineModel(id);
		});
		
		type_choice.addEventListener("change", () => {
			let type = type_choice.value;
			if(type === "xbox") {
				xbox.style.display = "block";
				playStation.style.display = "none";
			} else if (type === "ps") {
				xbox.style.display = "none";
				playStation.style.display = "block";
			}
		});
		
		const displayGamePadList = () => {
			gamepad_choice.innerHTML = "";
			
			if(Object.keys(gamepad_list).length === 0) {
				gamepad_choice.innerHTML = '<option value="0">No gamepad connected</option>';
			} else {
				Object.keys(gamepad_list).map((index) => {
					let value = index;
					let name = gamepad_list[index].id;
					gamepad_choice.innerHTML += `<option value=${value}>${name}</option>`;
				});	
			}
		}
		
		const nonLinearMapping = (x, y) => {
			let newX = x * Math.sqrt(1 - 0.5 * Math.pow(y, 2));
			let newY = y * Math.sqrt(1 - 0.5 * Math.pow(x, 2)); 
			return [newX, newY];
		}
		
		const linearMapping = (x) => {
			return (x + 1) / 2;
		}
		
		const pollGamepads = () => {
			let style = type_choice.value;
			selected_index = gamepad_choice.value;
			
			if(Object.keys(gamepad_list).length === 0) {
				return false;
			} else {
				let gp = navigator.getGamepads()[selected_index];
				for(let j=0;j<gp.buttons.length;j++){
					let button = gp.buttons[j];
					
					if(button_layout[style][j]) {
						let id = `${style}-${button_layout[style][j]}`;
						let pressed_button = window.document.getElementById(id);
						
						if(pressed_button) {
							if(button && button.pressed){
								if(button_layout[style][j] === 'Touchpad') {
									touchpad_press = true;
								}
								pressed_button.classList.add('visited');
								pressed_button.classList.add('active');
							} else if(button && !button.pressed) {
								pressed_button.classList.remove('active');
								touchpad_press = false;
							}
							
							if(j === 6 || j === 7) {
								let moveY = gp.buttons[j].value * 60;
								let pressed_button_path = window.document.getElementById(`${id}-Path`);
								pressed_button.setAttribute('transform', `translate(0, ${moveY})`);
								pressed_button_path.setAttribute('transform', `translate(0, ${moveY})`);
							}
							
						}	
					}
				}
				
				let axis = {
					L: [gp.axes[0], gp.axes[1], gp.axes[4]],
					R: [gp.axes[2], gp.axes[3], gp.axes[5]],
				}
				
				Object.keys(axis).map((direction) => {
					let analog = window.document.getElementById(`${style}-${direction}Analog`);
					let analogPath = window.document.getElementById(`${style}-${direction}Analog-Path`);
					
					let [x, y, p] = axis[direction];
					let [newX, newY] = nonLinearMapping(x, y);
					let newP = linearMapping(p);
					
					newX = newX * 40;
					newY = newY * 40;

					analog.setAttribute('transform', `translate(${newX}, ${newY})`);
					analogPath.setAttribute('transform', `translate(${newX}, ${newY})`);
					
					if(analog.classList.contains('active')) {
						analog.style.opacity = newP;
					} else {
						analog.style.opacity = 1;
					}
				});
				
			}
		} 
		
		const vibrateGamepad = (index, duration) => {
			var gamepad = navigator.getGamepads()[index];

			if (!gamepad) {
				console.log("No gamepad found at index " + index);
			} else if(!("vibrationActuator" in gamepad) || !gamepad["vibrationActuator" ]) {
				statusInfo.innerHTML = "<span><?php the_field('no_vibration_title');?></span>";
				setTimeout(() => {
					statusInfo.innerHTML = "";
				}, 5000);
			} else {
				gamepad.vibrationActuator.playEffect("dual-rumble", {
					startDelay: 0,
					duration: duration,
					weakMagnitude: 1.0,
					strongMagnitude: 1.0
				}).then(() => console.log("Vibration started")).catch(console.log);
			}
		}
		
		window.addEventListener('scroll', (e) => {
			if(touchpad_press) {
				e.preventDefault();
			}
		}, { passive: false });
		
		const preventDefaultBehavior = (e) => {
			if (touchpad_press) {
				e.preventDefault();
			}
		}

		// Stop scrolling when two fingers touch the touchpad
		const handleTouchMove = (e) => {
			if (e.touches.length === 2 && touchpad_press) {  // Check if two fingers are used
				e.preventDefault();
			}
		}
		
		window.addEventListener('touchstart', preventDefaultBehavior, { passive: false });
		window.addEventListener('touchmove', handleTouchMove, { passive: false });
		window.addEventListener('touchend', preventDefaultBehavior, { passive: false });
		
		vibrationBtn.addEventListener("click", () => {
			vibrateGamepad(gamepad_choice.value, 1000);
		});
		
		window.addEventListener("gamepadconnected", (e) => {
			var gp = navigator.getGamepads()[e.gamepad.index];
			console.log("GGGGPPP", gp);
			if(Object.keys(gamepad_list).length === 0) {
				determineModel(gp.id);
			}
			gamepad_list[e.gamepad.index] = gp;
			statusInfo.innerHTML = "";
			if(vibrationBtn.classList.contains("btn-effect")) {
				vibrationBtn.classList.remove("btn-effect");	
			}
			
			displayGamePadList();
		});

		window.addEventListener("gamepaddisconnected", (e) => {
			delete gamepad_list[e.gamepad.index];
			displayGamePadList();
			
			if(Object.keys(gamepad_list).length) {
				statusInfo.innerHTML = '<span class="loader"></span><span><?php the_field('loading_title');?></span>';
				vibrationBtn.classList.add("btn-effect");
			}
		});
		
		setInterval(pollGamepads, 1000/60);
		
	})(window, document);
</script>
<?php get_footer();
